def run(travel_related, destination, weather_results, travel_results):
    problems = []
    ok = True
    if not travel_related:
        return {'ok': False, 'problems': ['request is not travel-related']}
    if not isinstance(destination, str) or not destination.strip():
        problems.append('missing destination')
        ok = False
    if not weather_results or not isinstance(weather_results, list):
        problems.append('missing weather search results')
        ok = False
    if not travel_results or not isinstance(travel_results, list):
        problems.append('missing travel search results')
        ok = False
    return {'ok': ok, 'problems': problems}

def run(travel_related, question, destination, verify_ok, answer):
    if not travel_related:
        return {'speech': 'Sorry, I only help with travel questions.', 'report': '## Refusal\n\nThe request was not travel-related.', 'reason': 'non-travel'}
    if not verify_ok:
        dest = destination or 'the destination'
        return {'speech': f'I could not fully verify the travel details for {dest}.', 'report': '## Missing data\n\nSome needed travel details were not available, so I could not give a confident travel answer.', 'reason': 'missing-data'}
    return {'speech': answer or '', 'report': '', 'reason': 'handled'}

def run(travel_related, verify_ok, answer_type, speech, report, refusal, decline_speech, decline_report, question, destination, start_date, end_date, trip_length_days):
    if not travel_related:
        return {'speech': decline_speech, 'report': decline_report}
    if not verify_ok:
        return {'speech': decline_speech, 'report': decline_report}
    final_speech = speech or 'I have your travel answer.'
    final_report = report or '## Travel answer\n\nNo report was returned.'
    return {'speech': final_speech, 'report': final_report}
